<?php
namespace App\Http\Middleware;use App\Models\AuditLog;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class AuditAdminActions{public function handle(Request $r,Closure $next):Response{$response=$next($r);if($r->user()?->isAdmin()&&!in_array($r->method(),['GET','HEAD'])&&$response->getStatusCode()<400){$data=$r->except(['password','password_confirmation','smtp_password','_token']);AuditLog::create(['user_id'=>$r->user()->id,'action'=>$r->route()?->getActionMethod()??'action','route'=>$r->route()?->getName(),'method'=>$r->method(),'subject_type'=>collect($r->route()?->parameters()??[])->keys()->first(),'subject_id'=>($v=collect($r->route()?->parameters()??[])->first()) instanceof \Illuminate\Database\Eloquent\Model?$v->getKey():null,'changes'=>$data,'ip_address'=>$r->ip(),'user_agent'=>substr((string)$r->userAgent(),0,1000),'response_status'=>$response->getStatusCode()]);}return $response;}}
